-- Tacoma Community Hub · Thanksgiving 2026
-- Safe, isolated tables. Private contact details are separated from public gallery content.
create table if not exists public.hub_thanksgiving_campaigns(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,tagline text not null,start_date date not null,end_date date not null,is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date));
create table if not exists public.hub_thanksgiving_submissions(id uuid primary key default gen_random_uuid(),campaign_slug text not null references public.hub_thanksgiving_campaigns(slug),category text not null check(category in('gratitude','why-tacoma','community-hero','recipe-tradition','neighbor-story')),display_name text not null check(char_length(trim(display_name)) between 2 and 80),city text check(city is null or char_length(city)<=80),title text check(title is null or char_length(title)<=140),message text not null check(char_length(trim(message)) between 10 and 1800),media_url text check(media_url is null or(char_length(media_url)<=1000 and media_url ~* '^https://')),media_type text not null default 'none' check(media_type in('none','image','video','audio','external')),allow_hub_display boolean not null default false,allow_tacoma_nights boolean not null default false,allow_social boolean not null default false,guardian_consent boolean not null default false,status text not null default 'pending' check(status in('pending','reviewing','approved','featured','rejected','archived')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),check(allow_hub_display=true));
create table if not exists public.hub_thanksgiving_submission_contacts(submission_id uuid primary key references public.hub_thanksgiving_submissions(id) on delete cascade,email text check(email is null or(char_length(email)<=254 and position('@' in email)>1 and position('.' in split_part(email,'@',2))>1 and email not like '% %')),phone text check(phone is null or char_length(phone)<=40),contact_permission boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.hub_thanksgiving_partners(id uuid primary key default gen_random_uuid(),campaign_slug text not null references public.hub_thanksgiving_campaigns(slug),organization_name text not null check(char_length(trim(organization_name)) between 2 and 160),category text not null check(category in('nonprofit','food-bank','business','restaurant','faith-community','neighborhood','volunteer-group','other')),description text not null check(char_length(trim(description)) between 10 and 1200),website_url text check(website_url is null or(char_length(website_url)<=1000 and website_url ~* '^https://')),public_contact_url text check(public_contact_url is null or(char_length(public_contact_url)<=1000 and public_contact_url ~* '^https://')),status text not null default 'pending' check(status in('pending','approved','published','rejected','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.hub_thanksgiving_partner_contacts(partner_id uuid primary key references public.hub_thanksgiving_partners(id) on delete cascade,contact_name text not null,email text not null,permission_to_contact boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.hub_thanksgiving_resources(id uuid primary key default gen_random_uuid(),campaign_slug text not null references public.hub_thanksgiving_campaigns(slug),title text not null,organization text not null,category text not null check(category in('food','meal','volunteer','donation','family-support','community-gathering','other')),description text not null,website_url text not null check(website_url ~* '^https://'),location_text text,phone text,verification_status text not null default 'needs-review' check(verification_status in('needs-review','verified','expired')),verified_at timestamptz,valid_until date,status text not null default 'draft' check(status in('draft','published','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.hub_thanksgiving_events(id uuid primary key default gen_random_uuid(),campaign_slug text not null references public.hub_thanksgiving_campaigns(slug),title text not null,organization text,description text not null,starts_at timestamptz not null,ends_at timestamptz,location_text text,website_url text check(website_url is null or website_url ~* '^https://'),category text not null default 'community' check(category in('meal','food-drive','volunteer','community','business','other')),status text not null default 'pending' check(status in('pending','approved','published','rejected','cancelled','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or ends_at>=starts_at));
create table if not exists public.hub_thanksgiving_moderation_log(id bigint generated always as identity primary key,target_type text not null check(target_type in('submission','partner','resource','event')),target_id uuid not null,action text not null,note text,actor_id uuid not null references auth.users(id),created_at timestamptz not null default now());
create index if not exists hub_thanksgiving_submissions_public_idx on public.hub_thanksgiving_submissions(campaign_slug,status,created_at desc);
create index if not exists hub_thanksgiving_partners_public_idx on public.hub_thanksgiving_partners(campaign_slug,status,created_at desc);
create index if not exists hub_thanksgiving_resources_public_idx on public.hub_thanksgiving_resources(campaign_slug,status,category);
create index if not exists hub_thanksgiving_events_public_idx on public.hub_thanksgiving_events(campaign_slug,status,starts_at);
do $$ declare t text; begin foreach t in array array['hub_thanksgiving_campaigns','hub_thanksgiving_submissions','hub_thanksgiving_submission_contacts','hub_thanksgiving_partners','hub_thanksgiving_partner_contacts','hub_thanksgiving_resources','hub_thanksgiving_events','hub_thanksgiving_moderation_log'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
-- Policy creation is guarded so this migration can be reapplied in a fresh or partially provisioned environment.
do $$ begin
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_campaigns' and policyname='Public read active Thanksgiving campaigns') then create policy "Public read active Thanksgiving campaigns" on public.hub_thanksgiving_campaigns for select to anon,authenticated using(is_active); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_campaigns' and policyname='Hub admins manage Thanksgiving campaigns') then create policy "Hub admins manage Thanksgiving campaigns" on public.hub_thanksgiving_campaigns for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_submissions' and policyname='Public submit Thanksgiving stories') then create policy "Public submit Thanksgiving stories" on public.hub_thanksgiving_submissions for insert to anon,authenticated with check(status='pending' and reviewed_by is null and reviewed_at is null and allow_hub_display); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_submissions' and policyname='Public read approved Thanksgiving stories') then create policy "Public read approved Thanksgiving stories" on public.hub_thanksgiving_submissions for select to anon,authenticated using(status in('approved','featured')); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_submissions' and policyname='Hub admins manage Thanksgiving stories') then create policy "Hub admins manage Thanksgiving stories" on public.hub_thanksgiving_submissions for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_submission_contacts' and policyname='Hub admins manage Thanksgiving submission contacts') then create policy "Hub admins manage Thanksgiving submission contacts" on public.hub_thanksgiving_submission_contacts for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_submission_contacts' and policyname='Public can provide private Thanksgiving submission contact') then create policy "Public can provide private Thanksgiving submission contact" on public.hub_thanksgiving_submission_contacts for insert to anon,authenticated with check(contact_permission); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_partners' and policyname='Public submit Thanksgiving partners') then create policy "Public submit Thanksgiving partners" on public.hub_thanksgiving_partners for insert to anon,authenticated with check(status='pending'); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_partners' and policyname='Public read published Thanksgiving partners') then create policy "Public read published Thanksgiving partners" on public.hub_thanksgiving_partners for select to anon,authenticated using(status='published'); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_partners' and policyname='Hub admins manage Thanksgiving partners') then create policy "Hub admins manage Thanksgiving partners" on public.hub_thanksgiving_partners for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_partner_contacts' and policyname='Hub admins manage Thanksgiving partner contacts') then create policy "Hub admins manage Thanksgiving partner contacts" on public.hub_thanksgiving_partner_contacts for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_partner_contacts' and policyname='Public can provide private Thanksgiving partner contact') then create policy "Public can provide private Thanksgiving partner contact" on public.hub_thanksgiving_partner_contacts for insert to anon,authenticated with check(permission_to_contact); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_resources' and policyname='Public read verified Thanksgiving resources') then create policy "Public read verified Thanksgiving resources" on public.hub_thanksgiving_resources for select to anon,authenticated using(status='published' and verification_status='verified' and(valid_until is null or valid_until>=current_date)); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_resources' and policyname='Hub admins manage Thanksgiving resources') then create policy "Hub admins manage Thanksgiving resources" on public.hub_thanksgiving_resources for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_events' and policyname='Public submit Thanksgiving events') then create policy "Public submit Thanksgiving events" on public.hub_thanksgiving_events for insert to anon,authenticated with check(status='pending'); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_events' and policyname='Public read published Thanksgiving events') then create policy "Public read published Thanksgiving events" on public.hub_thanksgiving_events for select to anon,authenticated using(status='published'); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_events' and policyname='Hub admins manage Thanksgiving events') then create policy "Hub admins manage Thanksgiving events" on public.hub_thanksgiving_events for all to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))) with check(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_moderation_log' and policyname='Hub admins read Thanksgiving moderation log') then create policy "Hub admins read Thanksgiving moderation log" on public.hub_thanksgiving_moderation_log for select to authenticated using(exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
if not exists(select 1 from pg_policies where schemaname='public' and tablename='hub_thanksgiving_moderation_log' and policyname='Hub admins write Thanksgiving moderation log') then create policy "Hub admins write Thanksgiving moderation log" on public.hub_thanksgiving_moderation_log for insert to authenticated with check(actor_id=(select auth.uid()) and exists(select 1 from public.hub_admins a where a.user_id=(select auth.uid()) and lower(a.role) in('admin','moderator'))); end if;
end $$;
grant select on public.hub_thanksgiving_campaigns,public.hub_thanksgiving_submissions,public.hub_thanksgiving_partners,public.hub_thanksgiving_resources,public.hub_thanksgiving_events to anon,authenticated;
grant insert on public.hub_thanksgiving_submissions,public.hub_thanksgiving_submission_contacts,public.hub_thanksgiving_partners,public.hub_thanksgiving_partner_contacts,public.hub_thanksgiving_events to anon,authenticated;
grant usage,select on all sequences in schema public to authenticated;
grant select,insert,update,delete on public.hub_thanksgiving_campaigns,public.hub_thanksgiving_submissions,public.hub_thanksgiving_submission_contacts,public.hub_thanksgiving_partners,public.hub_thanksgiving_partner_contacts,public.hub_thanksgiving_resources,public.hub_thanksgiving_events,public.hub_thanksgiving_moderation_log to authenticated;
insert into public.hub_thanksgiving_campaigns(slug,title,tagline,start_date,end_date,is_active) values('thanksgiving-2026','Thanksgiving in Tacoma 2026','A Community. A Family. A Reason to Be Thankful.','2026-11-01','2026-11-29',true) on conflict(slug) do update set is_active=true,updated_at=now();
